import {type EditDef,type NodeDef,type PortType} from './model';
export const port=(id:string,type:PortType,required=true)=>({id,name:id,type,required});
export function node(id:string,kind:NodeDef['kind'],params:NodeDef['params'],inputs:NodeDef['inputs'],output:PortType):NodeDef{return {id,name:id,kind,params,inputs,outputs:[port('out',output)],ui:{x:0,y:0}};}
export function example(kind:'remove'|'speaker'|'cross'='remove'):EditDef {
  const source=node('source','media',{},[],'av'),detect=node('quiet','detection',{detector:'silence'},[port('media','av')],'signal'),when=node('long-pause','condition',{expression:{op:'threshold',signal:'value',on:2},debounce:.5},[port('value','signal')],'condition'),selection=node('selection','selection',{},[port('media','av'),port('condition','condition')],'selection'),action=node('remove','action',{action:'remove',mode:'propose'},[port('media','av'),port('selection','selection')],'av');
  const edit:EditDef={schemaVersion:1,id:kind,name:kind==='speaker'?'Speaker focus':kind==='cross'?'Cross-revision tagging':'Remove long silences',version:1,nodes:[source,detect,when,selection,action],connections:[],slots:[{id:'source',name:'Recording',nodeId:'source',type:'av',required:true}],history:[]};
  const wire=(from:string,to:string,input:string)=>edit.connections.push({from:{node:from,port:'out'},to:{node:to,port:input}});
  wire('source','quiet','media');wire('quiet','long-pause','value');wire('source','selection','media');wire('long-pause','selection','condition');wire('source','remove','media');wire('selection','remove','selection');
  if(kind==='cross'){const tag=node('tag-remaining','action',{action:'tag',label:'pause remainder',mode:'auto'},[port('media','av'),port('selection','selection')],'av');edit.nodes.push(tag);wire('remove','tag-remaining','media');wire('selection','tag-remaining','selection');}
  if(kind==='speaker'){
    detect.params={detector:'speaker',label:'speakerA'};when.params={expression:{op:'threshold',signal:'value',on:.5,off:.2},debounce:1.5,hold:3};action.params={action:'layout',layout:'speakerA',defaultLayout:'grid',mode:'review'};
    const b=node('speaker-b','detection',{detector:'speaker',label:'speakerB'},[port('media','av')],'signal'),both=node('both-speaking','condition',{expression:{op:'and',children:[{op:'threshold',signal:'a',on:.5,off:.2},{op:'threshold',signal:'b',on:.5,off:.2}]},debounce:1.5,hold:3},[port('a','signal'),port('b','signal')],'condition'),s=node('both-selection','selection',{},[port('media','av'),port('condition','condition')],'selection'),layout=node('show-both','action',{action:'layout',layout:'both',defaultLayout:'grid',z:1,mode:'review'},[port('media','av'),port('selection','selection')],'av');edit.nodes.push(b,both,s,layout);wire('source','speaker-b','media');wire('quiet','both-speaking','a');wire('speaker-b','both-speaking','b');wire('source','both-selection','media');wire('both-speaking','both-selection','condition');wire('remove','show-both','media');wire('both-selection','show-both','selection');
    const onlyB=node('b-active','condition',{expression:{op:'threshold',signal:'b',on:.5,off:.2},debounce:1.5,hold:3},[port('b','signal')],'condition'),selectB=node('b-selection','selection',{},[port('media','av'),port('condition','condition')],'selection'),showB=node('show-b','action',{action:'layout',layout:'speakerB',defaultLayout:'grid',z:0,mode:'review'},[port('media','av'),port('selection','selection')],'av');edit.nodes.push(onlyB,selectB,showB);wire('speaker-b','b-active','b');wire('source','b-selection','media');wire('b-active','b-selection','condition');wire('remove','show-b','media');wire('b-selection','show-b','selection');edit.connections=edit.connections.filter(c=>!(c.from.node==='remove'&&c.to.node==='show-both'));wire('show-b','show-both','media');
  }
  edit.nodes.forEach((n,i)=>n.ui={x:40+i*200,y:40});return edit;
}
