import {type TimeMap,type Range,type Segment} from './model';
const epsilon=1e-8;
export function validateMap(map:TimeMap){let end=0;for(const s of map.segments){if(!Object.values(s).every(Number.isFinite)||s.outStart<end-epsilon||s.outEnd<=s.outStart||s.srcEnd<=s.srcStart||s.srcStart<0||s.rate<=0||Math.abs((s.srcEnd-s.srcStart)/(s.outEnd-s.outStart)-s.rate)>epsilon)throw Error('Invalid time map: use ordered, positive-rate segments.');end=s.outEnd;}}
export function sourceTime(map:TimeMap,time:number){const s=map.segments.find(s=>time>=s.outStart&&time<s.outEnd);return s?s.srcStart+(time-s.outStart)*s.rate:undefined;}
export function project(map:TimeMap,time:number):number[]{return map.segments.filter(s=>time>=s.srcStart&&time<s.srcEnd).map(s=>s.outStart+(time-s.srcStart)/s.rate);}
export function inverse(map:TimeMap):TimeMap {const segments=map.segments.map(s=>({outStart:s.srcStart,outEnd:s.srcEnd,srcStart:s.outStart,srcEnd:s.outEnd,rate:1/s.rate})).sort((a,b)=>a.outStart-b.outStart);const result={segments};validateMap(result);return result;}
/** local maps new output → parent; parent maps parent → origin. */
export function compose(local:TimeMap,parent:TimeMap):TimeMap {const segments:Segment[]=[];for(const a of local.segments)for(const b of parent.segments){const lo=Math.max(a.srcStart,b.outStart),hi=Math.min(a.srcEnd,b.outEnd);if(hi<=lo)continue;segments.push({outStart:a.outStart+(lo-a.srcStart)/a.rate,outEnd:a.outStart+(hi-a.srcStart)/a.rate,srcStart:b.srcStart+(lo-b.outStart)*b.rate,srcEnd:b.srcStart+(hi-b.outStart)*b.rate,rate:a.rate*b.rate});}segments.sort((a,b)=>a.outStart-b.outStart);return {segments};}
export function mergeRanges(ranges:Range[]):Range[]{const result:Range[]=[];for(const r of [...ranges].sort((a,b)=>a.start-b.start)){if(!Number.isFinite(r.start)||!Number.isFinite(r.end)||r.start<0||r.end<r.start)throw Error('Ranges need finite start/end times, with end after start.');if(r.end===r.start)continue;const last=result.at(-1);if(last&&r.start<=last.end){last.end=Math.max(last.end,r.end);last.confidence=Math.min(last.confidence??1,r.confidence??1);}else result.push({...r});}return result;}
export function rangeProjection(map:TimeMap,ranges:Range[]):{ranges:Range[];lost:Range[]} {
  const output:Range[]=[],lost:Range[]=[];
  for(const r of ranges){const covered:Range[]=[];for(const s of map.segments){const lo=Math.max(r.start,s.srcStart),hi=Math.min(r.end,s.srcEnd);if(hi<=lo)continue;covered.push({start:lo,end:hi});output.push({...r,start:s.outStart+(lo-s.srcStart)/s.rate,end:s.outStart+(hi-s.srcStart)/s.rate});}let cursor=r.start;for(const c of mergeRanges(covered)){if(c.start>cursor+epsilon)lost.push({...r,start:cursor,end:c.start});cursor=Math.max(cursor,c.end);}if(cursor<r.end-epsilon)lost.push({...r,start:cursor,end:r.end});}
  return {ranges:output.sort((a,b)=>a.start-b.start),lost};
}
export function toOrigin(map:TimeMap,ranges:Range[]):Range[]{const output:Range[]=[];for(const r of ranges)for(const s of map.segments){const a=Math.max(r.start,s.outStart),b=Math.min(r.end,s.outEnd);if(b>a)output.push({...r,start:s.srcStart+(a-s.outStart)*s.rate,end:s.srcStart+(b-s.outStart)*s.rate});}return output;}
